/**
 * Fetches real-time verified news using Google Search Grounding.
 */
export const fetchLatestNews = async (category: string) => {
  try {
    const prompt = `Find the 5 most recent and verified news articles or updates for Nigerian students related to "${category}". 
    Focus on news from the last 24-72 hours. 
    Include:
    1. A catchy headline.
    2. A short 2-sentence summary.
    3. The primary category.
    4. The date published.

    Format the output as a valid JSON array of objects with properties: title, excerpt, category, date. 
    Do not add any markdown formatting like \`\`\`json. Just the raw array.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        // We don't use responseMimeType: "application/json" here because search grounding works better with standard text generation that we then parse.
      },
    });

    const text = response.text || "[]";
    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;

    // Attempt to parse the AI's response
    try {
      // Clean potential markdown code blocks if the AI ignored instructions
      const cleanJson = text.replace(/```json/g, "").replace(/```/g, "").trim();
      const articles = JSON.parse(cleanJson);

      // Attach grounding URLs to the articles
      const chunks = groundingMetadata?.groundingChunks || [];
      return articles.map((article: any, index: number) => ({
        ...article,
        url: chunks[index]?.web?.uri || chunks[0]?.web?.uri || "https://google.com/search?q=" + encodeURIComponent(article.title)
      }));
    } catch (e) {
      console.error("JSON Parsing failed for news", e);
      return [];
    }
  } catch (error) {
    console.error("Fetch News Error:", error);
    return [];
  }
};

