import React, { useEffect } from 'react';

interface AdPlaceholderProps {
  slot?: string;
  format?: 'auto' | 'fluid' | 'rectangle';
  className?: string;
  style?: React.CSSProperties;
}

declare global {
  interface Window {
    adsbygoogle: any[];
  }
}

const AdPlaceholder: React.FC<AdPlaceholderProps> = ({ 
  slot, 
  format = 'auto', 
  className,
  style = { display: 'block' }
}) => {
  useEffect(() => {
    // Only attempt to push if we are in a browser environment and not in development (optional check)
    try {
      if (typeof window !== 'undefined') {
        (window.adsbygoogle = window.adsbygoogle || []).push({});
      }
    } catch (e) {
      console.error("AdSense error:", e);
    }
  }, [slot]); // Re-run if slot changes

  // If no slot is provided, show the placeholder style
  if (!slot) {
    return (
      <div className={`bg-slate-100 border-2 border-dashed border-slate-300 rounded-lg flex items-center justify-center p-4 min-h-[100px] ${className}`}>
        <div className="text-center">
          <p className="text-slate-400 text-xs font-mono mb-1">ADVERTISEMENT</p>
          <p className="text-slate-300 text-[10px] uppercase">Slot ID Required</p>
        </div>
      </div>
    );
  }

  return (
    <div className={`ad-container overflow-hidden rounded-lg ${className}`}>
      <ins
        className="adsbygoogle"
        style={style}
        data-ad-client="ca-pub-5345604333370357"
        data-ad-slot={slot}
        data-ad-format={format}
        data-full-width-responsive="true"
      ></ins>
    </div>
  );
};

export default AdPlaceholder;

import React, { useState, useEffect } from 'react';

const CookieConsent: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const consent = localStorage.getItem('mindgrid_cookie_consent');
    if (!consent) {
      const timer = setTimeout(() => setIsVisible(true), 2000);
      return () => clearTimeout(timer);
    }
  }, []);

  const accept = () => {
    localStorage.setItem('mindgrid_cookie_consent', 'true');
    setIsVisible(false);
  };

  if (!isVisible) return null;

  return (
    <div className="fixed bottom-0 left-0 right-0 z-[100] p-4 pointer-events-none">
      <div className="max-w-4xl mx-auto bg-slate-900 text-white p-6 rounded-2xl shadow-2xl flex flex-col md:flex-row items-center justify-between gap-4 pointer-events-auto border border-white/10">
        <div className="text-sm">
          <p className="font-semibold mb-1">We value your privacy 🍪</p>
          <p className="text-slate-400">We use cookies to enhance your experience, serve personalized ads (via Google AdSense), and analyze our traffic. By clicking "Accept", you consent to our use of cookies.</p>
        </div>
        <div className="flex gap-3 shrink-0">
          <button 
            onClick={accept}
            className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded-xl font-bold text-sm transition-colors"
          >
            Accept All
          </button>
        </div>
      </div>
    </div>
  );
};

export default CookieConsent;

