import { GoogleGenAI, Type } from "@google/genai";

/**
 * MindGrid AI Configuration
 * The API key must be injected via Vite's 'define' config in vite.config.ts
 */
const API_KEY = process.env.API_KEY;

// Create AI instance. If key is missing, this will fail on use.
const ai = new GoogleGenAI({ apiKey: API_KEY });

/**
 * Checks if the AI is properly configured
 */
export const isAIConfigured = () => {
  return !!API_KEY && API_KEY.length > 5;
};

/**
 * Generates study help or mentorship advice.
 * Uses Pro model for complex educational reasoning.
 */
export const generateStudyHelp = async (query: string) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: query,
      config: {
        systemInstruction: `You are MindGrid AI, a specialized academic tutor for Nigerian students.
        Primary Goal: Help students understand complex concepts in WAEC/JAMB subjects and Tech.
        Knowledge Base: Highly proficient in Nigerian curriculum, University requirements, and Tech skills.
        Tone: Professional, expert, encouraging, and clear.
        Restriction: Never encourage cheating. Always provide step-by-step explanations.`,
        temperature: 0.7,
      },
    });

    if (!response.text) throw new Error("EMPTY_RESPONSE");
    return response.text;
  } catch (error: any) {
    console.error("MindGrid AI Error:", error);
    throw error;
  }
};

/**
 * Generates an AI-powered study schedule based on user goals.
 */
export const generateAISchedule = async (goal: string) => {
  if (!isAIConfigured()) return null;

  try {
    const prompt = `Create a balanced weekly study timetable for a Nigerian student preparing for: "${goal}". 
    The schedule should cover Monday to Sunday. 
    For each day, provide 2-3 specific study sessions with a subject name and a focus topic.
    Format the output as a JSON array of objects. Each object should have 'day' (string), and 'sessions' (array of {subject, topic}).`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              day: { type: Type.STRING },
              sessions: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    subject: { type: Type.STRING },
                    topic: { type: Type.STRING }
                  },
                  required: ["subject", "topic"]
                }
              }
            },
            required: ["day", "sessions"]
          }
        }
      }
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Schedule Gen Error:", error);
    return null;
  }
};

/**
 * Fetches real-time verified news using Google Search Grounding.
 */
export const fetchLatestNews = async (category: string) => {
  if (!isAIConfigured()) return [];

  try {
    const prompt = `Find the 5 most recent and verified news articles or updates for Nigerian students related to "${category}". 
    Format as JSON array: {title, excerpt, category, date}.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              excerpt: { type: Type.STRING },
              category: { type: Type.STRING },
              date: { type: Type.STRING }
            },
            required: ["title", "excerpt", "category"]
          }
        }
      },
    });

    const articles = JSON.parse(response.text.trim());
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return articles.map((article: any, index: number) => ({
      ...article,
      url: chunks[index]?.web?.uri || chunks[0]?.web?.uri || "https://google.com/search?q=" + encodeURIComponent(article.title)
    }));
  } catch (error) {
    console.error("News Fetch Error:", error);
    return [];
  }
};

/**
 * Fetches trending social media topics for Nigerian students.
 */
export const fetchSocialBuzz = async () => {
  if (!isAIConfigured()) return [];

  try {
    const prompt = `Identify 6 trending topics currently buzzing among Nigerian university students on Twitter/X, TikTok, and Instagram in the last 48 hours.
    Format as JSON array: {platform, topic, explanation, trendLevel}.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        temperature: 0.9,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              platform: { type: Type.STRING },
              topic: { type: Type.STRING },
              explanation: { type: Type.STRING },
              trendLevel: { type: Type.NUMBER }
            },
            required: ["platform", "topic", "explanation", "trendLevel"]
          }
        }
      },
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Social Buzz Error:", error);
    return [];
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { generateStudyHelp, isAIConfigured } from '../services/geminiService';

interface Message {
  role: 'user' | 'assistant';
  text: string;
}

const AIHub: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'assistant', text: "Hello! I'm MindGrid AI. I've been upgraded to help you solve JAMB problems, explain complex topics, and guide your tech journey. What are we studying today?" }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [configError, setConfigError] = useState(!isAIConfigured());
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    if (!isAIConfigured()) {
      setConfigError(true);
      return;
    }

    const userMsg = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput('');
    setIsLoading(true);

    try {
      const aiResponse = await generateStudyHelp(userMsg);
      setMessages(prev => [...prev, { role: 'assistant', text: aiResponse || "I'm sorry, I couldn't process that. Please try again." }]);
    } catch (error: any) {
      console.error("Chat Error:", error);
      let errorMsg = "I'm having trouble connecting to my brain right now. Please check your internet connection.";

      if (error.message === 'API_KEY_MISSING') {
        errorMsg = "System Error: The AI Key is missing from the environment. Please contact support.";
        setConfigError(true);
      } else if (error.status === 403 || error.status === 401) {
        errorMsg = "Access Denied: The AI Key might be invalid or expired.";
      }

      setMessages(prev => [...prev, { role: 'assistant', text: errorMsg }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12 flex flex-col h-[80vh]">
      {configError && (
        <div className="mb-4 p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center gap-3 text-red-700 animate-bounce">
          <i className="fas fa-exclamation-triangle text-xl"></i>
          <div>
            <p className="font-bold text-sm">AI Connection Warning</p>
            <p className="text-xs">The application cannot find a valid API Key. If you are the owner, please set the <code className="bg-red-100 px-1 rounded">API_KEY</code> environment variable in your Vercel/Netlify dashboard.</p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-t-3xl shadow-xl flex-grow flex flex-col overflow-hidden border border-slate-100">
        <div className="bg-green-600 p-4 text-white flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-white/20 p-2 rounded-lg">
              <i className="fas fa-robot"></i>
            </div>
            <div>
              <h1 className="font-bold">MindGrid Study Assistant Pro</h1>
              <p className="text-xs text-green-100">Online and ready to tutor</p>
            </div>
          </div>
          <button 
            onClick={() => setMessages([{ role: 'assistant', text: "Chat history cleared. How can I help you now?" }])}
            className="text-xs bg-white/10 hover:bg-white/20 px-3 py-1 rounded-full transition-colors"
          >
            Clear Chat
          </button>
        </div>

        <div className="flex-grow overflow-y-auto p-6 space-y-4 bg-slate-50">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-4 rounded-2xl shadow-sm ${
                msg.role === 'user' 
                  ? 'bg-green-600 text-white rounded-tr-none' 
                  : 'bg-white text-slate-800 border border-slate-200 rounded-tl-none'
              }`}>
                <p className="whitespace-pre-wrap text-sm leading-relaxed">{msg.text}</p>
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 flex items-center gap-2">
                <div className="flex gap-1">
                  <div className="w-2 h-2 bg-green-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-2 h-2 bg-green-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-2 h-2 bg-green-500 rounded-full animate-bounce"></div>
                </div>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">MindGrid is thinking...</span>
              </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        <div className="p-4 bg-white border-t border-slate-100">
          <div className="flex gap-2">
            <input
              type="text"
              placeholder="Explain the Nitrogen cycle in simple terms..."
              className={`flex-grow bg-slate-50 border ${configError ? 'border-red-200' : 'border-slate-200'} rounded-xl px-4 py-3 focus:ring-2 focus:ring-green-500 outline-none transition-all`}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            />
            <button
              onClick={handleSend}
              disabled={isLoading || !input.trim()}
              className="bg-green-600 text-white p-3 rounded-xl hover:bg-green-700 transition-colors disabled:opacity-50 shadow-md active:scale-95"
            >
              <i className="fas fa-paper-plane"></i>
            </button>
          </div>
          <p className="text-[10px] text-slate-400 text-center mt-2 uppercase tracking-tighter">AI may generate inaccurate information. Use official JAMB/WAEC materials as primary source.</p>
        </div>
      </div>
    </div>
  );
};

