import React, { useEffect, useRef } from 'react';

interface AdPlaceholderProps {
  slot?: string;
  format?: 'auto' | 'fluid' | 'rectangle';
  className?: string;
  style?: React.CSSProperties;
}

declare global {
  interface Window {
    adsbygoogle: any[];
  }
}

const AdPlaceholder: React.FC<AdPlaceholderProps> = ({ 
  slot, 
  format = 'auto', 
  className,
  style = { display: 'block' }
}) => {
  const adRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let timer: any;

    const tryPush = () => {
      // Check if the component is still mounted and the container has width
      if (adRef.current) {
        const width = adRef.current.offsetWidth;

        if (width > 0) {
          try {
            if (typeof window !== 'undefined') {
              (window.adsbygoogle = window.adsbygoogle || []).push({});
            }
          } catch (e) {
            console.error("AdSense push error:", e);
          }
        } else {
          // If width is 0, wait and try again. This happens during initial render or animations.
          timer = setTimeout(tryPush, 100);
        }
      }
    };

    if (slot) {
      tryPush();
    }

    return () => {
      if (timer) clearTimeout(timer);
    };
  }, [slot]);

  // If no slot is provided, show the placeholder style
  if (!slot) {
    return (
      <div className={`bg-slate-100 border-2 border-dashed border-slate-300 rounded-lg flex items-center justify-center p-4 min-h-[100px] ${className}`}>
        <div className="text-center">
          <p className="text-slate-400 text-xs font-mono mb-1">ADVERTISEMENT</p>
          <p className="text-slate-300 text-[10px] uppercase">Slot ID Required</p>
        </div>
      </div>
    );
  }

  return (
    <div ref={adRef} className={`ad-container overflow-hidden rounded-lg ${className}`}>
      <ins
        className="adsbygoogle"
        style={style}
        data-ad-client="ca-pub-5345604333370357"
        data-ad-slot={slot}
        data-ad-format={format}
        data-full-width-responsive="true"
      ></ins>
    </div>
  );
};

export default AdPlaceholder;

import { GoogleGenAI, Type } from "@google/genai";

/**
 * MindGrid AI Configuration
 * The API key must be injected via Vite's 'define' config in vite.config.ts
 */
const API_KEY = process.env.API_KEY;

// Create AI instance. If key is missing, this will fail on use.
const ai = new GoogleGenAI({ apiKey: API_KEY });

/**
 * Checks if the AI is properly configured
 */
export const isAIConfigured = () => {
  return !!API_KEY && API_KEY.length > 5;
};

/**
 * Helper to handle daily caching in localStorage
 */
const withDailyCache = async <T>(key: string, forceRefresh: boolean, fetcher: () => Promise<T>): Promise<T> => {
  const today = new Date().toISOString().split('T')[0];
  const cacheKey = `mindgrid_cache_${key}`;

  if (!forceRefresh) {
    const cached = localStorage.getItem(cacheKey);
    if (cached) {
      try {
        const { date, data } = JSON.parse(cached);
        if (date === today) {
          console.log(`[MindGrid AI] Using daily cached data for: ${key}`);
          return data;
        }
      } catch (e) {
        console.warn("Cache parse error", e);
      }
    }
  }

  const data = await fetcher();
  localStorage.setItem(cacheKey, JSON.stringify({ date: today, data }));
  return data;
};

/**
 * Generates study help or mentorship advice.
 * This is a live chat, so we don't cache it daily.
 */
export const generateStudyHelp = async (query: string) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: query,
      config: {
        systemInstruction: `You are MindGrid AI, a specialized academic tutor for Nigerian students.
        Primary Goal: Help students understand complex concepts in WAEC/JAMB subjects and Tech.
        Knowledge Base: Highly proficient in Nigerian curriculum, University requirements, and Tech skills.
        Tone: Professional, expert, encouraging, and clear.
        Restriction: Never encourage cheating. Always provide step-by-step explanations.`,
        temperature: 0.7,
      },
    });

    if (!response.text) throw new Error("EMPTY_RESPONSE");
    return response.text;
  } catch (error: any) {
    console.error("MindGrid AI Error:", error);
    throw error;
  }
};

/**
 * Generates an AI-powered study schedule based on user goals.
 */
export const generateAISchedule = async (goal: string) => {
  if (!isAIConfigured()) return null;

  return withDailyCache(`schedule_${goal.replace(/\s+/g, '_').toLowerCase()}`, false, async () => {
    try {
      const prompt = `Create a balanced weekly study timetable for a Nigerian student preparing for: "${goal}". 
      The schedule should cover Monday to Sunday. 
      Format the output as a JSON array of objects. Each object should have 'day' (string), and 'sessions' (array of {subject, topic}).`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                day: { type: Type.STRING },
                sessions: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      subject: { type: Type.STRING },
                      topic: { type: Type.STRING }
